import {TEAMS,LEAGUES} from './config.js';
import {fitNeeds,recruitmentReview} from './teams.js';
import {toolLabel,defenseRate} from './tools.js';
import {random} from './random.js';
import {CONFIG,CATEGORIES,TIERS,BUCKETS} from './config.js';
import {report} from './candidates.js';
import {rates,innings} from './stats.js';
import {createSession,startDraft,pick,available,eligible,recommended,playerPicks,otherInterest,firstCompetition,selectTeam,acceptTeamContext} from './draft.js';
import {revealCareers,isRecordedAward} from './career.js';
import {REASONS,evidence,contextualScouts,compareCandidates,toggleComparison,setReason,reasonReview,developmentReview} from './scouting.js';
import {watchedCandidates,revealWatched,lostCandidates} from './watchlist.js';
import {loadSession,saveSession,deleteSession} from './storage.js';
import {requestDraftCareerAd} from './ads.js';
import {formatMoney} from './format.js';
import {evaluateCareer} from './evaluation.js';
import {candidateNumbers,orderCandidates} from './candidate-order.js';

const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,extra='')=>`<button data-action="${action}" ${extra}>${label}</button>`,tag=x=>`<span class="tag">${esc(x)}</span>`;
let {state:s,error}=loadSession(),filters={scope:'注目候補',category:'すべて',role:'すべて',tier:'すべて'},detailId=null,detailTab='概要',busy=false,pendingLottery=null;
$('#status').textContent=error;
function persist(){const error=saveSession(s);$('#status').textContent=error;}
function fresh(){window.scrollTo(0,0);const seed=globalThis.crypto?.getRandomValues(new Uint32Array(1))[0]??Date.now();s=createSession(seed,CONFIG,null);filters.scope='注目候補';persist();render();}
function statLine(role,st){const r=rates(st);return role==='投手'?`${st.games}登板 / ${innings(st)}回 / 防御率${r.era.toFixed(2)} / ${st.so}奪三振`:`${st.games}試合 / 打率${r.avg.toFixed(3)} / ${st.hr}本 / OPS ${r.ops.toFixed(3)}`;}
function metrics(role,st){const r=rates(st),pairs=role==='投手'?[['防御率',r.era.toFixed(2)],['投球回',innings(st)],['勝利',st.wins],['奪三振',st.so],['WHIP',r.whip.toFixed(2)]]:[['打率',r.avg.toFixed(3)],['安打',st.hits],['本塁打',st.hr],['打点',st.rbi],['OPS',r.ops.toFixed(3)]];return `<div class="metrics">${pairs.map(([l,v])=>`<span>${l}<b>${v}</b></span>`).join('')}</div>`;}
function statDetails(role,st){const r=rates(st);const pairs=role==='投手'?[['登板',st.games],['投球回',innings(st)],['勝',st.wins],['敗',st.losses],['防御率',r.era.toFixed(2)],['奪三振',st.so],['与四球',st.bba],['与死球',st.hbpa],['被安打',st.ha],['被本塁打',st.hra],['失点',st.runs],['自責',st.er],['WHIP',r.whip.toFixed(2)],['K/BB',r.kbb===null?'—':r.kbb.toFixed(2)],['被打率',r.baa.toFixed(3)],['セーブ',st.saves],['ホールド',st.holds]]:[['試合',st.games],['打数',st.ab],['安打',st.hits],['二塁打',st.doubles],['三塁打',st.triples],['本塁打',st.hr],['打点',st.rbi],['盗塁',st.sb],['四球',st.bb],['死球',st.hbp],['三振',st.so],['打率',r.avg.toFixed(3)],['出塁率',r.obp.toFixed(3)],['長打率',r.slg.toFixed(3)],['OPS',r.ops.toFixed(3)],['BB%',r.bbPercent.toFixed(1)],['K%',r.kPercent.toFixed(1)]];return `<div class="year-stat">${pairs.map(([l,v])=>`<span>${l} <b>${v}</b></span>`).join('')}</div>`;}
function card(c){const declared=s.declarations.filter(id=>id===c.id).length;return `<article class="card prospect"><div class="prospect-name"><small class="serial">資料 ${String(candidateNumbers(s).get(c.id)).padStart(2,'0')}</small><h3>${esc(c.name)}</h3><p>${c.age}歳 / ${c.position} / ${c.hand}<span class="profile-body">${c.height}cm・${c.weight}kg</span></p><small>${esc(c.school)}</small><div>${tag(c.category)}${tag(c.tier)}</div></div><div class="prospect-report"><p class="stat-line">${esc(statLine(c.role,c.history.at(-1).stats))}</p><p>${c.role==='投手'?`最速 ${c.velocity}km/h`:`打球 ${c.exitVelocity}km/h / 守備 ${toolLabel(c.defenseTools?.range??50)} / 肩 ${toolLabel(c.defenseTools?.arm??50)} / 走力 ${toolLabel(c.defenseTools?.speed??50)}`}</p>${evidenceView(c,true)}${candidateFit(c)}<small>医療：${c.medical.length?'故障申告あり':'長期離脱の申告なし'} / 調査書 ${c.surveys}球団${declared?` / 1位予告 ${declared}球団`:''}</small></div><div class="actions prospect-actions">${button('candidate','資料を読む',`data-id="${c.id}"`)}${button('compare-toggle',(s.compareIds||[]).includes(c.id)?'比較から外す':'比較に追加',`data-id="${c.id}" aria-pressed="${(s.compareIds||[]).includes(c.id)}"`)}${button('favorite',s.favorites.includes(c.id)?'検討中':'検討リストへ',`data-id="${c.id}" aria-pressed="${s.favorites.includes(c.id)}"`)}${['first','rounds'].includes(s.phase)?button('pick','指名',`data-id="${c.id}" ${eligible(c,s.round,s.round>s.config.mainDraftRounds)?'':'disabled'} class="primary"`):''}<small>${s.reasons?.[c.id]?'指名理由：'+esc(s.reasons[c.id]):'資料内で指名理由を記録できます'}</small>${c.condition!=='制限なし'?`<small>${esc(c.condition)}</small>`:''}</div></article>`;}

function select(name,options){return `<label>${name==='scope'?'表示':name==='category'?'所属':name==='role'?'守備位置':'世間評価'}<select data-filter="${name}">${options.map(v=>`<option ${filters[name]===v?'selected':''}>${v}</option>`).join('')}</select></label>`;}
function listing(){let list=orderCandidates(s,(s.phase==='scouting'?s.candidates:available(s)).map(report));if(filters.scope==='注目候補')list=list.filter(c=>c.rank<=CONFIG.featuredCount);if(filters.scope==='球団要望に合う候補')list=list.filter(c=>fitNeeds(c,s.teamNeeds).length);if(filters.scope==='お気に入り')list=list.filter(c=>s.favorites.includes(c.id));if(filters.scope==='マイボード')list=list.filter(c=>s.board[c.id]);list=list.filter(c=>(filters.category==='すべて'||c.category===filters.category)&&(filters.role==='すべて'||(filters.role==='内野'?['一塁','二塁','三塁','遊撃'].includes(c.position):filters.role==='外野'?['左翼','中堅','右翼'].includes(c.position):c.position===filters.role||c.role===filters.role))&&(filters.tier==='すべて'||c.tier===filters.tier));return `<div class="filters">${select('scope',['注目候補','全候補','球団要望に合う候補','お気に入り','マイボード'])}${select('category',['すべて',...CATEGORIES])}${select('role',['すべて','投手','捕手','内野','外野'])}${select('tier',['すべて',...TIERS])}</div><p class="muted">${list.length}人を表示 / 未指名 ${available(s).length}人。1位・上位・中位・下位・育成の順。区分内の資料番号は評価順位ではありません。</p>${comparisonBar()}<div class="prospect-list">${list.map(card).join('')||'<p class="empty">該当なし。「全候補」に切り替えて探せます。</p>'}</div>`;}
function boardNeeds(){return '<div class="board-needs"><h3>チームからの要望</h3>'+((s.teamNeeds||[]).map(n=>'<p><b>'+esc(n.priority)+'：'+esc(n.label)+'</b><br><small>未指名の該当候補 '+available(s).filter(c=>fitNeeds(report(c),[n]).length).length+'人</small></p>').join('')||'<p>このドラフトには要望の記録がありません。</p>')+'</div>';}
function board(){const list=orderCandidates(s,s.candidates.filter(c=>s.board[c.id]));return `<details><summary>マイボード ${list.length}人 / 外れ1位 ${s.fallbacks.length}人</summary>${boardNeeds()}${list.map(c=>`<div class="board-row">${button('candidate',esc(c.name),`data-id="${c.id}"`)}${tag(s.board[c.id])}<small>${c.tier}・予告${s.declarations.filter(id=>id===c.id).length}・調査${c.surveys} / 面談${c.interviews}</small></div>`).join('')||'<p>候補資料から「1位・上位・中位・育成」に登録できます。</p>'}<p>外れ1位の控え：${s.fallbacks.map(id=>esc(s.candidates.find(c=>c.id===id).name)).join(' → ')||'未登録'}</p></details>`;}
function draftView(){const mine=playerPicks(s),first=s.phase==='first',next=recommended(s)[0];return `<section><h1>${first?'1位入札':s.round>s.config.mainDraftRounds?'育成指名':s.round+'位指名'}</h1><p>${first&&s.lotteries.length?'抽選に外れました。残っている選手から再入札してください。':teamName()+'の指名です。'}</p><p class="muted">獲得 ${mine.length} / 5人。2位以降は偶数巡が逆順のウェーバー方式です。</p>${next&&(s.fallbacks.length||Object.keys(s.board).length)?button('pick',`自分のボード：${esc(next.name)}を指名`, `data-id="${next.id}" class="primary"`):''}<details><summary>直前の抽選・他球団の指名</summary>${s.lotteries.slice(-1).flat().filter(x=>x.teams.length>1).map(x=>`<p>${esc(s.candidates.find(c=>c.id===x.id).name)}：${x.teams.length}球団競合 → ${esc(s.clubs[x.winner].team)}</p>`).join('')}<ul class="news">${s.news.slice(0,20).map(n=>`<li>${esc(n)}</li>`).join('')}</ul></details>${board()}</section>${listing()}`;}
function render(){
 const assignment=$('#assignment');assignment.textContent=s&&s.playerTeam!==null?teamName()+' / 編成責任者':'';
 if(s?.phase==='team-select'){$('#app').innerHTML=teamSelectView();return;}
 if(s?.phase==='team-context'){$('#app').innerHTML='<section><h1>あなたの球団を知る</h1><p>あなたは'+teamName()+'の編成責任者です。</p>'+teamNeedsView()+button('candidates','ドラフト候補へ','class="primary"')+'</section>';return;}

 if(!s){$('#app').innerHTML=`<section class="intro"><small class="edition">編成会議 / 2026年度</small><h1>その指名に、<br>あなたの読みを。</h1><p>高校からの成績、身体の変化、スカウトの意見。他球団の動向を読み、未来へ賭ける5人を選びます。</p><p>12球団・76候補。支配下4人＋育成1人を指名したら、引退までを一気に答え合わせ。</p>${button('start','ドラフトを始める','class="primary"')}<p class="muted">目安3〜5分。資料をじっくり読むなら10〜20分。進行はこのブラウザに自動保存されます。</p></section>`;return;}
 if(s.phase==='scouting')$('#app').innerHTML=`<section><small class="edition">${CONFIG.startYear}年度 / スカウト資料</small><h1>ドラフト候補名簿</h1><p>あなたは${teamName()}の編成責任者。まずは注目${CONFIG.featuredCount}人から。全${s.candidates.length}人を調べることもできます。</p><div class="actions">${button('team-needs','球団事情・補強ポイント')}${button('intelligence','他球団の動向')}</div>${board()}<div class="draft-entry">${button('begin','ドラフト会議へ進む','class="primary draft-start"')}<small>支配下4人＋育成1人を指名します。</small></div><p class="desktop-note">評価は公表された実績と取材からの予想です。将来の活躍を保証するものではありません。</p></section>${listing()}`;
 else if(['first','rounds'].includes(s.phase))$('#app').innerHTML=draftView();
 else if(s.phase==='drafted')$('#app').innerHTML=`<section><h1>5人の未来を、答え合わせ。</h1>${needReviewView()}<p>全${s.picks.length}指名が確定。${available(s).length}人が未指名となりました。</p>${button('reveal',busy?'結果を準備中…':'その後を見る',`class="primary" ${busy?'disabled':''}`)}</section><div class="grid">${playerPicks(s).map(p=>{const c=s.candidates.find(c=>c.id===p.id);return `<article class="card">${tag(p.development?'育成':p.round+'位')}<h3>${esc(c.name)}</h3><p>${c.category}・${c.position}</p><details><summary>他球団の評価を公開</summary>${otherInterest(s,c.id).map(x=>`<p>${x.team}：ボード${x.rank}番目</p>`).join('')}<small>指名開始時のCPUボードです。会議中は獲得状況に応じて優先順位を調整します。次の指名を確約する順位ではありません。</small></details></article>`;}).join('')}</div>`;
 else $('#app').innerHTML=`<section><small class="edition">指名総括 / キャリア記録</small><h1>5人が歩んだ野球人生</h1>${needReviewView(s.results)}<p>順位に対する期待と、選手自身の実績は分けて振り返ります。</p>${button('again','もう一度、見抜く','class="primary"')}</section>${lostCandidatesView()}<div class="grid results">${s.results.map(saved=>{const r=reviewResult(saved);return `<article class="card">${tag(r.pick.development?'育成':r.pick.round+'位')}${tag(r.classification)}<h2>${esc(r.name)}</h2><small>指名順位への評価</small><br><b>${r.verdict}</b><p class="career-narrative">${esc(r.narrative||r.evaluation?.narrative||"")}</p><p><small>補強目的</small><br>${esc(r.evaluation?.needReview||"")}</p><p>${r.years}年間 / ${r.retirementAge}歳で引退 / 最高年俸 ${formatMoney(r.highestSalary)}</p>${metrics(r.role,r.total)}<p>${r.titles.filter(t=>isRecordedAward(t.title)&&t.title!=='オールスター').slice(0,4).map(t=>esc(t.title)).join('・')||'主要タイトルなし'}</p>${button('result','キャリアを詳しく見る',`data-id="${r.id}"`)}</article>`;}).join('')}</div>${watchlistView()}`;
}
function dialog(html){$('#detail').innerHTML=`<div class="dialog-head"><small>${s&&s.playerTeam!==null?teamName()+" / 編成責任者":"白球ドラフト"}</small>${button('close','閉じる')}</div><div class="dialog-body">${html}</div>`;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;$('.dialog-body').scrollTop=0;}
function candidateDetail(id,tab='概要'){
 detailId=id;detailTab=tab;const c=report(s.candidates.find(c=>c.id===id));const header=`<h2>${esc(c.name)}</h2><p>${c.age}歳 / ${c.position} / ${c.hand}<span class="profile-body">${c.height}cm・${c.weight}kg</span><br>${esc(c.school)}</p><div class="tabs">${['概要','成績・成長','詳細データ'].map(t=>button('detail-tab',t,`data-tab="${t}" ${tab===t?'class="selected"':''}`)).join('')}</div>`;
 let content='';if(tab==='概要')content=`${tag(c.tier)}${tag(c.movement)}${tag(c.condition)}${metrics(c.role,c.history.at(-1).stats)}<p>${c.height}cm・${c.weight}kg / ${c.representative||'代表選出の記録なし'}</p>${c.family?`<p>${c.family}。家族の経歴は選手本人の実力と分けて評価。</p>`:''}${candidateFit(c)}${evidenceView(c)}${reasonEditor(c)}${button('compare-toggle',(s.compareIds||[]).includes(c.id)?'比較から外す':'比較に追加',`data-id="${c.id}"`)}${toolsView(c)}${personalityView(c)}<h3>スカウトノート</h3>${contextualScouts(c).map(x=>`<p>${esc(x)}</p>`).join('')}${surveyView(c)}<h3>マイボード</h3><div class="actions">${BUCKETS.map(b=>button('bucket',b,`data-id="${c.id}" data-bucket="${b}" ${s.board[id]===b?'class="selected"':''}`)).join('')}${button('fallback',s.fallbacks.includes(id)?'外れ1位から外す':'外れ1位の控えへ',`data-id="${id}"`)}</div>${s.phase==='scouting'?button('declare',s.declarations[s.playerTeam]===id?'この1位予告を撤回':'この選手の1位指名を予告',`data-id="${id}"`):''}`;
 else if(tab==='成績・成長')content=`<p class="muted">打率などは年度ごとの実数から算出。大会成績は別枠です。少数試合は偶然の影響も大きくなります。</p>${c.history.map(y=>`<details ${y.age===c.age?'open':''}><summary>${y.year}年 / ${y.age}歳 / ${y.label}</summary><p>${y.league} / ${y.height}cm ${y.weight}kg / ${c.role==='投手'?'最速 '+y.velocity+'km/h':'打球速度 '+y.exitVelocity+'km/h'}</p>${statDetails(c.role,y.stats)}${defenseView(y.defense)}<p>${y.injury?`${y.injury.part}で${y.injury.days}日離脱${y.injury.surgery?'・手術あり':''}`:'長期離脱の記録なし'}${y.slump?' / 計測・試合内容に不調の時期あり':''}</p>${y.national?`<h3>全国大会・強豪との対戦</h3>${statDetails(c.role,y.national.stats)}`:'<p>全国大会の記録なし</p>'}</details>`).join('')}`;
 else{const y=c.history.at(-1);content=`${toolsView(c)}${personalityView(c)}<h3>現在地とプロでの見方</h3><p>${c.projection}</p><h3>メディカル</h3><p>${c.medicalFinding}</p>${c.medical.map(m=>`<p>${m.year}年 ${m.part} / ${m.days}日${m.surgery?' / 手術':''}</p>`).join('')}<h3>${c.role==='投手'?'球種・球質':'打球・身体計測'}</h3>${c.role==='投手'?c.pitches.map(p=>`<p><b>${p.name}</b> ${p.velocity}km/h / ${p.spin}rpm<br>空振り${p.whiff}%・ストライク${p.strike}%<br><small>${p.note}</small></p>`).join('')+`<p>通常${c.velocity}km/h / セット${c.setVelocity}km/h。走者を背負った投球を引き続き確認。</p>`:`<p>最高打球速度 ${c.contact.exitVelocity}km/h / 強い打球 ${c.contact.hardHit}%<br>スイング ${c.contact.swing}km/h / 逆方向 ${c.contact.opposite}%<br>50m走 ${c.contact.run50}秒 / 送球 ${c.contact.throw}km/h</p>`}<h3>左右別の直近成績</h3><small>別々の試合群を集計した目安。完全な打席単位トラッキングではありません。</small><details><summary>対右 ${y.splits.right.games}試合</summary>${statDetails(c.role,y.splits.right)}</details><details><summary>対左 ${y.splits.left.games}試合</summary>${statDetails(c.role,y.splits.left)}</details><h3>場面別の観察試合</h3><p class="muted">直近の試合・練習試合から場面ごとに別集計。年度通算には加算しません。少数試合の参考値です。</p>${Object.entries(y.situations).map(([k,v])=>`<details><summary>${({empty:"走者なし",runners:"走者あり・セット",fastball:"速球中心の投手",breaking:"変化球中心の投手",risp:"得点圏の対戦"})[k]}</summary>${statDetails(c.role,v)}</details>`).join('')}<p>${esc(c.observation)}</p>`;}
 dialog(header+content);
}
function resultDetail(id){const saved=s.results.find(r=>r.id===id)||s.watchedResults?.[id];if(!saved)return;const r=reviewResult(saved);dialog(`<small class="edition">${esc(TEAMS[r.pick.team])} / ${r.pick.development?"育成":r.pick.round+"位"}指名</small><h2>${esc(r.name)}のキャリア</h2>${tag(r.classification)}<p>${r.verdict} / ${r.years}年 / 生涯年俸${formatMoney(r.totalSalary)}</p>${metrics(r.role,r.total)}<p class="career-narrative">${esc(r.narrative||"")}</p><h3>補強目的への評価</h3><p>${esc(r.evaluation?.needReview||"旧αで未記録")}</p><h3>指名理由の記録</h3><p class="reason-review">${esc(reasonReview(r))}</p>${developmentReviewView(r)}<h3>指名時の読みと、その後</h3>${r.answers.map(x=>`<p>${esc(x)}</p>`).join('')}<details><summary>通算成績・二軍／マイナー</summary><h3>一軍・海外トップ</h3>${statDetails(r.role,r.total)}<h3>二軍・マイナー</h3>${statDetails(r.role,r.farmTotal)}</details><details open><summary>全年度成績 ${r.rows.length}年</summary>${r.rows.map(y=>`<details><summary class="${y.year===r.careerHigh?'best':''}">${y.year}年 ${y.age}歳 / ${y.team}${y.year===r.careerHigh?' / キャリアハイ':''}</summary><p>${(y.positions||[y.position]).join(' / ')}・${y.role} / 年俸${formatMoney(y.salary)} / 離脱${y.injuryDays}日</p>${statDetails(r.role,y.stats)}${defenseView(y.defense)}<details><summary>二軍・マイナー</summary>${statDetails(r.role,y.farm)}</details><p>${y.awards.filter(isRecordedAward).join('・')}</p></details>`).join('')}</details><details><summary>タイトル・表彰 ${r.titles.filter(x=>isRecordedAward(x.title)).length}件</summary>${r.honorsModel?'<p>同年度・同リーグの既存選手と今回の指名選手の成績を比較して決定。首位打者は規定打席、最優秀防御率は規定投球回を満たす選手が対象です。</p>':'<p>旧版で保存された獲得記録を表示しています。</p>'}${r.titles.filter(x=>isRecordedAward(x.title)).map(x=>`<p>${x.year}年 ${x.age}歳 ${x.title}</p>`).join('')||'<p>記録なし</p>'}</details><details><summary>故障歴 ${r.injuries.length}件</summary>${r.injuries.map(x=>`<p>${x.year}年 ${x.age}歳 ${x.part} ${x.days}日</p>`).join('')||'<p>記録なし</p>'}</details><details><summary>キャリア年表</summary>${r.events.filter(x=>x.type!=='AWARD'||isRecordedAward(x.text)).map(x=>`<p>${x.year}年 ${x.age}歳 ${esc(x.text)}</p>`).join('')}</details>`);}
function confirmReset(deleting=false){dialog(`<h2>${deleting?'白球ドラフトの保存を削除しますか？':'新しいドラフトを始めますか？'}</h2><p>現在のドラフトと5人の結果が上書きされます。白球人生のデータは変更しません。</p><div class="actions">${button(deleting?'confirm-delete':'confirm-reset',deleting?'削除する':'新しいドラフトへ')}${button('close','キャンセル')}</div>`);}
document.addEventListener('click',async e=>{if(e.detail>1)return;const b=e.target.closest('[data-action]');if(!b||busy)return;const {action,id}=b.dataset;try{
 if(action==='compare-toggle'){toggleComparison(s,id);persist();render();if($('#detail').open)candidateDetail(id,detailTab);return;}
 if(action==='compare-open'){comparisonDialog();return;}
 if(action==='watch-result'){const result=revealWatched(s,id);persist();if(result.undrafted)dialog('<h2>指名なし</h2><p>'+esc(result.route)+'</p><p>未指名選手の将来をプロの成績として生成しません。</p>');else resultDetail(id);return;}
 if(action==='close'){pendingLottery=null;$('#detail').close();return;}
 if(action==='draw-lottery'){if(!pendingLottery)return;const target=pendingLottery;pendingLottery=null;await drawLottery(target);return;}
 if(action==='start'){fresh();return;}if(action==='select-team'){selectTeam(s,Number(id));persist();render();window.scrollTo(0,0);return;}if(action==='random-team'){selectTeam(s,random(`${s.seed}:player-team`).int(0,s.config.teamCount-1));persist();render();return;}if(action==='candidates'){acceptTeamContext(s);persist();render();window.scrollTo(0,0);return;}if(action==='team-needs'){dialog(teamNeedsView());return;}if(action==='again'){confirmReset();return;}
 if(action==='confirm-reset'){$('#detail').close();fresh();return;}if(action==='confirm-delete'){const error=deleteSession();$('#status').textContent=error;if(!error){s=null;$('#detail').close();render();}return;}
 if(action==='candidate'){candidateDetail(id);return;}if(action==='detail-tab'){candidateDetail(detailId,b.dataset.tab);return;}if(action==='result'){resultDetail(id);return;}
 if(action==='favorite'){s.favorites=s.favorites.includes(id)?s.favorites.filter(x=>x!==id):[...s.favorites,id];}
 if(action==='bucket'){if(s.board[id]===b.dataset.bucket)delete s.board[id];else s.board[id]=b.dataset.bucket;persist();render();candidateDetail(id,detailTab);return;}
 if(action==='fallback'){s.fallbacks=s.fallbacks.includes(id)?s.fallbacks.filter(x=>x!==id):[...s.fallbacks,id];persist();candidateDetail(id);return;}
 if(action==='declare'){s.declarations[s.playerTeam]=s.declarations[s.playerTeam]===id?null:id;persist();candidateDetail(id);return;}
 if(action==='intelligence'){dialog(`<h2>他球団の動向</h2><p>1位予告は初回入札で実行されます。予告なしでも競合する場合があります。</p>${s.clubs.map((c,i)=>({...c,index:i})).filter(c=>c.index!==s.playerTeam).map(c=>`<p><b>${c.team}</b><br>編成思想：${c.philosophy}<br>補強観点：${c.needs.map(n=>n.label).join("・")}<br>${s.declarations[c.index]?'1位予告：'+esc(s.candidates.find(p=>p.id===s.declarations[c.index]).name):'1位は未公表。複数候補を比較中。'}</p>`).join('')}`);return;}
 if(action==='begin'){startDraft(s);filters.scope='全候補';window.scrollTo(0,0);}if(action==='pick'){if(s.phase==='first'){const teams=firstCompetition(s,id);if(teams.length>1){pendingLottery=id;lotteryDialog(id,teams);return;}}pick(s,id);$('#detail').close();window.scrollTo(0,0);}
 if(action==='reveal'){busy=true;render();try{await requestDraftCareerAd(s,{persist});revealCareers(s);window.scrollTo(0,0);}finally{busy=false;pendingLottery=null;}}
 persist();render();
 }catch(err){$('#status').textContent=`操作を完了できませんでした：${err.message}`;busy=false;pendingLottery=null;}});
document.addEventListener('change',e=>{if(e.target.dataset.reasonId){try{setReason(s,e.target.dataset.reasonId,e.target.value);persist();render();}catch(err){$('#status').textContent=err.message;}return;}if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;render();}});
$('#detail').addEventListener('cancel',e=>{if(busy)e.preventDefault();else pendingLottery=null;});
$('#reset').onclick=()=>{if(!busy)s?confirmReset():fresh();};$('#delete').onclick=()=>{if(!busy)confirmReset(true);};render();

function teamName(){return s&&s.playerTeam!==null?TEAMS[s.playerTeam]:'';}
function reviewResult(r){const c=s.candidates.find(c=>c.id===r.id),needs=s.legacyNeeds?null:r.pick.team===s.playerTeam?s.needsAtDraft||s.teamNeeds:s.clubs[r.pick.team].needs,e=evaluateCareer(r,c,needs);return {...r,evaluation:e,classification:e.absolute,verdict:e.expectation,narrative:e.narrative};}
function developmentReviewView(r){const c=s.candidates.find(c=>c.id===r.id),d=developmentReview(r,c);if(!d)return '';return '<details class="development-review" open><summary>指名時とプロ入り後を比較</summary><p>'+esc(d.summary)+'</p><div class="table-wrap"><table class="development-table"><thead><tr><th>見る点</th><th>指名時の資料</th><th>プロ入り後の実績</th></tr></thead><tbody>'+d.rows.map(row=>'<tr>'+row.map(cell=>'<td>'+esc(cell)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><small>アマチュアとプロは対戦水準・試合数が異なります。数値の増減だけで成長・失敗とは判定しません。</small></details>';}
function lotteryDialog(id,teams){const c=s.candidates.find(c=>c.id===id);dialog('<section class="lottery"><small class="edition">'+(s.lotteries.length?'外れ1位の再入札':'1位指名')+'</small><h2>'+esc(c.name)+' / '+teams.length+'球団競合</h2><p>当選確率 <b>1 / '+teams.length+'（'+(100/teams.length).toFixed(1)+'%）</b><br>全球団が同じ確率の抽選です。</p><ul>'+teams.map(t=>'<li>'+esc(TEAMS[t])+'</li>').join('')+'</ul>'+button('draw-lottery','くじを引く','class="primary"')+'</section>');}
async function drawLottery(id){
 busy=true;const round=s.lotteries.length;
 try{dialog('<section class="lottery drawing" aria-live="polite"><h2>抽選中</h2><div class="lottery-ticket">抽選くじ</div></section>');pick(s,id);persist();render();
  if(!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches)await new Promise(resolve=>setTimeout(resolve,600));
  const ballot=s.lotteries[round].find(b=>b.id===id),won=ballot.winner===s.playerTeam,c=s.candidates.find(c=>c.id===id);
  dialog('<section class="lottery lottery-result" aria-live="polite"><small class="edition">抽選結果</small><h2>'+esc(c.name)+'</h2><p class="lottery-verdict">'+(won?'交渉権獲得':'抽選に外れました')+'</p><p>交渉権：'+esc(TEAMS[ballot.winner])+'</p>'+button('close',won?'次の指名へ':'外れ1位へ進む','class="primary"')+'</section>');
 }finally{busy=false;}
}
function teamSelectView(){return '<section><h1>担当球団を選ぶ</h1><p>あなたが操作するのは1球団。ほかの11球団は、それぞれの補強事情に基づいて指名します。</p>'+button('random-team','ランダムで決める')+'</section>'+LEAGUES.map((league,i)=>'<section><h2>'+league+'</h2><div class="grid">'+TEAMS.slice(i*6,i*6+6).map((t,j)=>button('select-team',t,'data-id="'+(i*6+j)+'"')).join('')+'</div></section>').join('');}
function teamNeedsView(){if(!s.teamNeeds)return '<p>旧αでは補強要求の記録がありません。</p>';return '<h2>'+teamName()+'の球団事情</h2><p>編成思想：'+esc(s.teamPhilosophy)+'</p>'+s.teamNeeds.map(n=>'<article class="need"><b>'+n.priority+'：'+n.label+'</b><p>'+n.reason+'</p></article>').join('')+'<details><summary>各守備位置の戦力と年齢層</summary>'+Object.entries(s.teamContext).map(([p,t])=>'<p>'+p+'：'+(t.strength>=70?'充実':t.strength>=50?'標準':'補強したい')+' / '+(t.age>=31?'高齢化':t.age<=27?'若手中心':'中堅中心')+' / '+(t.depth<=2?'層が薄い':'控えあり')+'</p>').join('')+'</details><p class="muted">球団の要求は命令ではありません。自分の読みを優先する指名も可能です。</p>';}
function candidateFit(c){const fits=fitNeeds(c,s.teamNeeds);return fits.length?'<p class="fit">補強候補像に合致：'+fits.map(n=>esc(n.label)).join('・')+'<small>（活躍の保証ではありません）</small></p>':'';}
function toolsView(c){if(c.role!=='野手')return '';return '<h3>守備・肩・走塁の観察</h3><p class="muted">スカウトによる推定。試合での再現性は別途確認します。</p><div class="year-stat">'+Object.entries({field:'守備',range:'守備範囲',catching:'捕球',throwing:'送球精度',arm:'肩',speed:'走力',running:'走塁判断',...(c.position==='捕手'?{blocking:'ブロッキング'}:{})}).map(([k,l])=>'<span>'+l+' <b>'+toolLabel(c.defenseTools?.[k]??50)+'</b></span>').join('')+'</div>';}
function personalityView(c){return '<h3>人物・面談</h3><p class="muted">情報源ごとの見方です。性格だけで将来は決まりません。</p>'+(c.personality||[]).map(p=>'<p><small>'+esc(p.source)+'</small><br>'+esc(p.text)+'</p>').join('');}
function defenseView(d){if(!d)return '';return '<details class="defense-stats"><summary>守備実績</summary><div class="year-stat">'+[['守備試合',d.games],['機会',d.chances],['失策',d.errors],['守備率',defenseRate(d)?.toFixed(3)??'—'],['刺殺',d.putouts],['補殺',d.assists],['併殺',d.doublePlays],['盗塁企図',d.attempts],['盗塁阻止',d.caught],['阻止率',d.attempts?(d.caught/d.attempts).toFixed(3):'—'],['捕逸',d.passedBalls],['守備貢献',d.contribution]].map(([k,v])=>'<span>'+k+' <b>'+v+'</b></span>').join('')+'</div><small>守備貢献は独自の簡易指標です。</small></details>';}
function needReviewView(results=null){const r=recruitmentReview(s,results);return '<details class="need-review" open><summary>球団補強との答え合わせ</summary><p>'+esc(r.summary)+'</p>'+r.items.map(n=>'<p><b>'+esc(n.label)+'：'+n.status+(n.milestone?' / '+n.milestone:'')+'</b><br>'+esc(n.text)+'</p>').join('')+'</details>';}

function evidenceView(c,brief=false){const e=evidence(c);return '<p class="evidence"><b>'+e.sample+'・'+e.volume+'</b><br>'+esc(e.competition)+' / '+e.strong+(brief?'':'<br><small>'+e.note+'</small>')+'</p>';}
function reasonEditor(c){const p=s.picks.find(p=>p.id===c.id);if(p)return '<p>記録した指名理由：'+esc(p.reason||'記録なし')+'</p>';return '<label class="reason-editor">指名理由（任意）<select data-reason-id="'+c.id+'"><option value="">記録しない</option>'+REASONS.map(x=>'<option '+(s.reasons?.[c.id]===x?'selected':'')+'>'+x+'</option>').join('')+'</select><small>実際に獲得できた時の理由として残ります。</small></label>';}
function comparisonBar(){const n=(s.compareIds||[]).length;return '<div class="compare-bar"><span>比較資料 <b>'+n+' / 3人</b></span>'+button('compare-open','並べて比較',n<2?'disabled':'')+'</div>';}
function comparisonDialog(){const candidates=compareCandidates(s);if(candidates.length<2)return;dialog('<h2>候補比較</h2><p>数字と、その数字が残った環境を読み比べる。</p><div class="comparison-grid">'+candidates.map(c=>'<article class="comparison-player"><small>'+esc(c.tier)+' / '+c.category+'</small><h3>'+esc(c.name)+'</h3><p>'+c.age+'歳 / '+c.position+' / '+c.hand+'<span class="profile-body">'+c.height+'cm・'+c.weight+'kg</span><br>'+esc(c.school)+'</p>'+metrics(c.role,c.history.at(-1).stats)+evidenceView(c)+toolsView(c)+'<h3>故障・想定される起用</h3><p>'+esc(c.medicalFinding)+'</p><p>'+esc(c.projection)+'</p>'+candidateFit(c)+'<h3>スカウト所見</h3>'+contextualScouts(c).map(x=>'<p>'+esc(x)+'</p>').join('')+reasonEditor(c)+button('candidate','詳しい資料へ','data-id="'+c.id+'"')+'</article>').join('')+'</div>');}
function lostCandidatesView(){const list=lostCandidates(s);if(!list.length)return '';return '<section class="watchlist lost-candidates"><small class="edition">くじの向こう側</small><h2>競合で逃した選手 '+list.length+'人</h2><p>他球団に入団した後の野球人生も、引退まで振り返れます。</p>'+list.map(c=>{const p=s.picks.find(p=>p.id===c.id),ballot=s.lotteries.flat().find(b=>b.id===c.id&&b.teams.includes(s.playerTeam)&&b.winner!==s.playerTeam);return '<div class="watch-row"><span><b>'+esc(c.name)+'</b><small>'+ballot.teams.length+'球団競合 / '+esc(TEAMS[p.team])+'・1位 / '+c.position+'</small></span>'+button('watch-result','その後を見る','data-id="'+c.id+'"')+'</div>';}).join('')+'</section>';}
function watchlistView(){const lost=new Set(lostCandidates(s).map(c=>c.id)),list=watchedCandidates(s).filter(c=>!lost.has(c.id));return '<section class="watchlist"><small class="edition">もう一つの選択</small><h2>見送った候補のその後</h2><p>検討リスト・比較・評価ボード・外れ候補の選手を振り返る。</p>'+list.map(c=>{const p=s.picks.find(p=>p.id===c.id);return '<div class="watch-row"><span><b>'+esc(c.name)+'</b><small>'+c.position+' / '+(p?TEAMS[p.team]+'・'+(p.development?'育成':p.round+'位'):'指名なし')+'</small></span>'+button('watch-result','その後を見る','data-id="'+c.id+'"')+'</div>';}).join('')+(list.length?'':'<p>今回、見送った検討候補の記録はありません。</p>')+'</section>';}

function surveyView(c){return `<p>調査書${c.surveys}球団・面談${c.interviews}球団。補強候補の検討や追加確認を含み、評価順位・指名確約ではありません。</p>${c.surveyDetails?.length?`<details><summary>各球団が調べている理由</summary>${c.surveyDetails.map(x=>`<p>${esc(x.team)}：${x.reasons.map(esc).join('・')}${x.interview?' / 面談あり':''}</p>`).join('')}</details>`:''}`;}